/* Additional H5 demo screens. All rules use FarmSystems and the app's single state/dialog. */
(()=>{
 'use strict';
 window.FarmExpansion={create(ctx){
  const {state,S,D,icon,cropArt,animalArt,photoArt,esc,btn}=ctx;
  const R=window.FarmRewards;
  const F=window.FarmDiscovery;
  let searchComposing=false,pendingSearchRender=false,compositionEndedAt=-Infinity;
  const shopFilters=[['all','全部商品'],['affordable','积分够兑'],['available','可加入'],['wishlist','我的心愿']];
  const taskFilters=[['all','全部'],['ready','待领取'],['todo','待完成'],['claimed','已领取']];
  const wishIds=()=>state.shopWishlist||[];
  function focusSearch(){document.querySelector('#shop-query')?.focus();}
  function handleComposition(event,active){
   if(event.target.id!=='shop-query')return;
   searchComposing=active;
   if(!active){compositionEndedAt=now();state.shopDraft=event.target.value.slice(0,64);if(pendingSearchRender){pendingSearchRender=false;ctx.render();}}
  }
  function handleKeyDown(event){
   if(event.target.id==='shop-query'&&event.key==='Enter'&&(searchComposing||event.isComposing||event.keyCode===229||now()-compositionEndedAt<50))event.preventDefault();
  }
  function deferRender(){
   if(searchComposing&&state.view==='shop'&&document.activeElement?.id==='shop-query'&&!ctx.getModal()){pendingSearchRender=true;return true;}
   return false;
  }
  function handleInput(event){
   if(event.target.id!=='shop-query')return;
   state.shopDraft=event.target.value.slice(0,64);
   const clear=document.querySelector('#shop-clear');if(clear)clear.hidden=!state.shopDraft.length;
  }
  function handleSubmit(event){
   if(event.target.id!=='shop-search')return false;
   event.preventDefault();if(searchComposing||event.isComposing)return true;
   state.shopQuery=event.target.querySelector('input').value.slice(0,64).trim();
   state.shopDraft=state.shopQuery;ctx.render();focusSearch();return true;
  }
  function discoveryControls(){
   const filter=state.shopFilter||'all',query=state.shopDraft??state.shopQuery??'';
   return `<section class="shop-discovery" aria-label="查找积分商品"><form id="shop-search" novalidate role="search"><label for="shop-query">想为田园添点什么？</label><div class="shop-search-row"><div class="shop-search-field">${icon('search')}<input id="shop-query" data-focus-key="shop-query" name="query" type="search" maxlength="64" enterkeyhint="search" autocomplete="off" placeholder="搜商品、饲料或肥料" value="${esc(query)}"><button type="button" id="shop-clear" data-action="x-search-clear" aria-label="清除商品搜索" ${query?'':'hidden'}>${icon('close')}</button></div><button type="submit" class="primary-button">查找</button></div></form><div class="discovery-filters" role="group" aria-label="商品筛选">${shopFilters.map(([key,label])=>btn('x-shop-filter',label+(key==='wishlist'?` <span>${wishIds().length}</span>`:''),'discovery-chip',`data-filter="${key}" aria-label="${label}" aria-pressed="${filter===key}"`)).join('')}</div><p class="discovery-help">${filter==='affordable'?'按单件原价与当前积分筛选；库存、购物车与优惠券在结算时核对。':filter==='wishlist'?'心愿只保留本次体验，刷新后清空。':'可按所需物资查找，组合包也能找到。'}</p></section>`;
  }
  function goalCard(){
   const g=F.goal(catalog,state.wallet,state.savingGoalSku);if(!g)return '';
   return `<section class="saving-goal" aria-labelledby="saving-goal-title"><div class="saving-goal-top"><span class="section-kicker">攒一份田园心意</span>${btn('x-goal-clear','结束目标','link-button')}</div><div class="saving-goal-main"><div class="saving-goal-art">${art(g.item.art)}</div><div><h2 id="saving-goal-title">${esc(g.item.title)}</h2><p>${g.shortfall?`还差 ${g.shortfall} 积分`:'积分已够兑一件'}</p></div></div><div class="saving-goal-progress" role="progressbar" aria-label="心愿商品积分进度" aria-valuemin="0" aria-valuemax="${g.item.cost}" aria-valuenow="${Math.min(g.points,g.item.cost)}"><span style="width:${g.percent}%"></span></div><div class="saving-goal-amount"><span>当前 ${g.points} 积分</span><span>单件 ${g.item.cost} 积分</span></div>${btn('x-goal-detail','回看心愿商品'+icon('chevron'),'outline-button full')}<p class="helper">按单件原价展示，不自动兑换。库存、优惠券和车中商品请在结算时核对。</p></section>`;
  }
  const now=()=>Date.now();
  const catalog=S.getCatalog();
  const ownViews=new Set(['activities','warehouse','cart','coupons','exchanges','rewards','achievements','tasks','album','messages']);
  const titles={activities:'田园活动',warehouse:'我的仓库',cart:'积分购物车',coupons:'我的优惠券',exchanges:'积分兑换记录',rewards:'活动奖励明细',achievements:'成长成就',tasks:'今日农事',album:'种养图鉴',messages:'农场消息'};
  const rewardText=r=>[r.points?`${r.points} 积分`:'',r.feed?`${r.feed} 份饲料`:'',r.fertilizer?`${r.fertilizer} 份肥料`:'',r.tools?`${r.tools} 件工具`:'',r.coupon?'积分优惠券':''].filter(Boolean).join(' + ');
  const countCart=()=>Object.values(state.system.cart).reduce((a,b)=>a+b,0);
  const receipt=type=>`sys-${type}-${now()}-${++state.systemSerial}`;
  const back=(to='farm',label='返回农场')=>btn(to,`${icon('back')}${label}`,'extension-back back-button');
  const returnLabel=to=>({cart:'返回购物车',shop:'返回商城',warehouse:'返回仓库',mine:'返回我的',rewards:'返回奖励明细'}[to]||'返回我的');
  function beforeNavigate(view){
   searchComposing=false;pendingSearchRender=false;
   if(view==='coupons'&&state.view!=='coupons')state.couponOrigin=['cart','shop','mine','rewards'].includes(state.view)?state.view:'mine';
   if(view==='exchanges'&&state.view!=='exchanges')state.exchangeOrigin=['warehouse','shop','mine'].includes(state.view)?state.view:'shop';
   if(view==='rewards'&&state.view!=='rewards'&&!(state.view==='coupons'&&state.couponOrigin==='rewards'))state.rewardOrigin=['activities','tasks','achievements','mine','warehouse'].includes(state.view)?state.view:'activities';
  }
  function navigationContext(){
   return {couponOrigin:['cart','shop','mine','rewards'].includes(state.couponOrigin)?state.couponOrigin:'mine',exchangeOrigin:['warehouse','shop','mine'].includes(state.exchangeOrigin)?state.exchangeOrigin:'shop',rewardOrigin:['activities','tasks','achievements','mine','warehouse'].includes(state.rewardOrigin)?state.rewardOrigin:'activities'};
  }
  function restoreNavigationContext(value){
   const saved=value&&typeof value==='object'&&!Array.isArray(value)?value:{};
   state.couponOrigin=['cart','shop','mine','rewards'].includes(saved.couponOrigin)?saved.couponOrigin:'mine';
   state.exchangeOrigin=['warehouse','shop','mine'].includes(saved.exchangeOrigin)?saved.exchangeOrigin:'shop';
   state.rewardOrigin=['activities','tasks','achievements','mine','warehouse'].includes(saved.rewardOrigin)?saved.rewardOrigin:'activities';
  }
  const pageHead=(title,sub)=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub||'田园里的每一份用心，都有回响。'}</p></div></div>`;
  const section=(title,action='',label='查看全部')=>`<div class="section-title"><h2>${title}</h2>${action?btn(action,label+icon('chevron'),'link-button'):''}</div>`;
  const quantity=(item,qty)=>`<div class="quantity-stepper" aria-label="${esc(item.title)}数量">${btn('x-quantity','−','',`data-sku="${item.id}" data-delta="-1" aria-label="减少${esc(item.title)}"`)}<span class="numeric" aria-live="polite">${qty}</span>${btn('x-quantity','＋','',`data-sku="${item.id}" data-delta="1" aria-label="增加${esc(item.title)}" ${qty>=Math.min(5,item.limit-(state.system.daily.bought[item.id]||0))?'disabled':''}`)}</div>`;
  const art=photoArt;
  function transact(result,success,detail){
   if(!result.ok){ctx.toast(result.reason);return false;}
   if(detail)state.rewardHistory=R.append(state.rewardHistory,{...detail,reward:result.reward});
   state.system=result.system;state.wallet=result.wallet;
   ctx.render();ctx.toast(success||result.reason);return true;
  }
  function claimReward(method,options,source,title){
   const at=now(),id=receipt(source),result=S[method](state.system,state.wallet,{...options,now:at,receiptId:id});
   return transact(result,result.ok?'已到账：'+rewardText(result.reward):'',{id,source,title,at});
  }
  function track(type,id,items){state.system=S.recordEvent(state.system,{type,eventId:id,now:now(),...(items?{items}:{})});}
  function assetRibbon(){const l=S.getLevel(state.system);return `<div class="asset-ribbon" aria-label="农场资产">${btn('achievements',`<span class="level-chip">Lv.${l.level}</span><span>${l.label}</span>`)}${btn('warehouse',`${icon('sprout')}<strong class="asset-value">${state.wallet.points}</strong><span>积分</span>`)}${btn('warehouse',`${icon('bag')}<strong class="asset-value">${state.wallet.feed}</strong><span>饲料</span>`)}</div>`;}
  function shortcuts(){return `<div class="farm-shortcuts" aria-label="农场快捷入口">${[['tasks','list','今日农事'],['warehouse','box','我的仓库'],['shop','bag','农场商城'],['activities','gift','田园活动']].map(([a,ic,label])=>btn(a,`${icon(ic)}<span>${label}</span>`,'shortcut')).join('')}</div>`;}
  function todayPanel(){const tasks=S.getTasks(state.system,now()),done=tasks.filter(t=>t.claimed).length,ready=tasks.filter(t=>t.ready&&!t.claimed).length;return `<div class="today-panel"><div class="today-head"><div><span class="section-kicker">今日农事</span><h3>把小事，照料成日常。</h3></div><span class="task-count">${done} / 3</span></div><div class="today-track"><span class="today-progress" style="width:${done/3*100}%"></span></div><div class="today-action"><p>${ready?`${ready} 项任务已有收获，记得领取积分。`:'逛田园、做照料、收获新鲜，完成今天的三件事。'}</p>${btn('tasks',ready?'去领取':'去看看','outline-button')}</div></div>`;}
  function home(html){
   const at=html.indexOf('<div class="segmented"');if(at>=0)html=html.slice(0,at)+assetRibbon()+html.slice(at);
   html=html.replace('<div class="harvest-strip"',shortcuts()+todayPanel()+'<div class="harvest-strip"');
   if(state.decoration){html=html.replace('<div class="hero">',`<div class="hero hero-decorated ${state.decoration==='garden-sign'?'decor-sign':'decor-frame'}"><span class="hero-decor-label">${state.decoration==='garden-sign'?'我的一方田':'丰收纪念 · HEJIAN'}</span>`);}
   return html;
  }
  function storeTabs(){return `<div class="store-tabs" role="group" aria-label="商城专区">${[['adopt','当季认养'],['supplies','农场物资'],['gifts','积分好礼']].map(([key,label])=>btn('x-store-tab',label,`store-tab ${state.storefront===key?'active':''}`,`data-tab="${key}" aria-pressed="${state.storefront===key}"`)).join('')}</div>`;}
  function storeWallet(){const count=countCart();return `<div class="store-wallet"><div><span>可用田园积分</span><strong>${state.wallet.points}</strong></div><div>${btn('coupons',`${icon('gift')}优惠券`,'link-button')}${btn('cart',`${icon('bag')}购物车${count?`<span class="cart-badge">${count}</span>`:''}`,'outline-button')}</div></div><div class="store-services" aria-label="商城服务">${btn('exchanges',`${icon('list')}积分兑换记录`,'link-button')}${btn('warehouse',`${icon('box')}我的仓库`,'link-button')}</div>`;}
  function renderDock(){
   if(state.view!=='shop'||state.storefront==='adopt')return '';
   const q=S.quoteCart(state.system,{couponId:state.selectedCoupon});
   if(!q.count)return '';
   return `<aside class="commerce-dock" aria-label="已选积分商品"><div class="commerce-dock-copy"><strong>已选 ${q.count} 件 · 小计 ${q.subtotal} 积分</strong><span>可用 ${state.wallet.points} 积分 · 优惠在购物车核对</span></div>${btn('cart','查看购物车','primary-button')}</aside>`;
  }
  function goodsAvailability(p){
   return F.availability(p,state.system);
  }
  const goodsSortOptions=[['recommended','推荐顺序'],['cost-asc','积分从低到高'],['cost-desc','积分从高到低']];
  function sortedGoods(category){
   return F.select(catalog,state.system,state.wallet,{category,query:state.shopQuery,filter:state.shopFilter,sort:state.goodsSort,wishlist:wishIds()});
  }
  function goodsSortControls(){return `<div class="goods-sorting" role="group" aria-label="积分商品排序">${goodsSortOptions.map(([key,label])=>btn('x-goods-sort',key==='cost-asc'?'积分低→高':key==='cost-desc'?'积分高→低':label,'goods-sort-button',`data-sort="${key}" aria-label="${label}" aria-pressed="${(state.goodsSort||'recommended')===key}"`)).join('')}</div>`;}
  function goodsCards(category){
   const items=sortedGoods(category),emptyWish=state.shopFilter==='wishlist'&&!wishIds().length;
   const empty=`<div class="discovery-empty"><div class="discovery-empty-mark">${icon(emptyWish?'heart':'search')}</div><h3>${emptyWish?'还没有心愿商品':'没有找到合适的商品'}</h3><p>${emptyWish?'打开商品详情，存下一份喜欢的田园心意。':'试试其他名称，或清除搜索与筛选再看看。'}</p>${btn('x-discovery-reset',emptyWish?'去挑选商品':'查看全部商品','outline-button')}</div>`;
   return `${discoveryControls()}${goodsSortControls()}<p id="goods-results" class="discovery-result" role="status" aria-live="polite">${state.shopQuery?'搜索「'+esc(state.shopQuery)+'」 · ':''}本专区 ${items.length} 件商品${state.shopFilter==='wishlist'?' · 我的心愿':''}</p>${items.length?`<div class="goods-grid">${items.map(p=>{const a=goodsAvailability(p);return `<article class="goods-card">${btn('x-goods-detail',`${art(p.art)}<span class="goods-tag">${wishIds().includes(p.id)?icon('heart')+'我的心愿':p.category==='gifts'?'田园好礼':'日常所需'}</span>`,'goods-art',`data-sku="${p.id}" aria-label="查看${esc(p.title)}详情"`)}<h3>${p.title}</h3><p>${p.description}</p><div class="goods-stock"><span>今日剩余 ${a.remaining} 件</span><span>车中 ${a.inCart} 件 · 还可加 ${a.canAdd} 件</span></div><div class="product-footer"><span class="goods-cost">${p.cost}<small> 积分 / 件</small></span>${btn('x-add-cart',a.unavailable||(a.inCart?'再加入':'加入'),'goods-add primary-button',`data-sku="${p.id}" ${a.canAdd===0?'disabled':''} aria-label="${a.unavailable?`${esc(p.title)}，${a.unavailable}`:`加入${esc(p.title)}到购物车`}"`)}</div></article>`;}).join('')}</div>`:empty}`;
  }
  function shop(adoptionHtml){
   let body=adoptionHtml;body=body.replace(/<div class="info">[\s\S]*?<\/div>/,`<div class="recommend-note"><span>当季推荐优先 · 比较周期与收获价值</span>${btn('recommend-info','推荐依据','link-button')}</div>`);const start=body.indexOf('<div class="segmented"');if(start>=0)body=body.slice(start);
   return `<div class="store-hero"><span class="section-kicker">HEJIAN FARM STORE</span><span class="photo-source">AI生成示意</span><h1>把田园所需，<br>好好备齐。</h1><p>选当季，备物资，收一份田园好礼。</p></div>${storeWallet()}${storeTabs()}${state.storefront==='adopt'?body:`<div class="adoption-toolbar"><h2>${state.storefront==='supplies'?'日常照料，刚刚好':'让田园，多一点心意'}</h2>${btn('warehouse','查看仓库'+icon('chevron'),'link-button')}</div>${goodsCards(state.storefront)}<div class="info">${icon('shield')}<span>使用田园积分兑换，全部为演示物资。增加饲料或肥料不会解除照料间隔与次数限制。</span></div>`}`;
  }
  function taskCards(compact=false){const tasks=S.getTasks(state.system,now()),filter=compact?(state.activityTaskFilter||'all'):'all',items=tasks.filter(t=>filter==='all'||filter==='ready'&&t.ready&&!t.claimed||filter==='todo'&&!t.ready&&!t.claimed||filter==='claimed'&&t.claimed);if(!items.length)return `<div class="task-filter-empty" role="status">${icon('checkCircle')}<h3>${filter==='ready'?'没有待领取的任务奖励':filter==='claimed'?'还没有已领取的任务':'今日任务都已完成'}</h3><p>${filter==='ready'?'完成农事后再来看看，已领取的奖励可在明细中核对。':filter==='claimed'?'先完成任务，再领取对应奖励。':'可以看看成长成就与丰收集章。'}</p>${btn('x-task-filter','查看全部任务','outline-button','data-filter="all"')}</div>`;return items.map(t=>`<article class="task-card"><div class="task-icon">${icon(t.id==='browse'?'leaf':t.id==='care'?'drop':'basket')}</div><div class="task-copy"><h3>${t.title}</h3><p>${t.description}</p><span class="task-reward">+ ${rewardText(t.reward)}</span><div class="task-progress-label"><span>任务进度</span><span>${t.progress} / ${t.target}</span></div><div class="task-progress" role="progressbar" aria-label="${t.title}进度" aria-valuemin="0" aria-valuemax="${t.target}" aria-valuenow="${Math.min(t.progress,t.target)}"><span style="width:${Math.min(100,t.progress/t.target*100)}%"></span></div></div><div class="task-action">${btn(t.ready?'x-claim-task':'x-task-go',t.claimed?'已领取':t.ready?'领取':'去完成',t.ready?'primary-button':'outline-button',`data-task="${t.id}" ${t.claimed?'disabled':''}`)}</div></article>`).join('');}
  function signInCard(){
   const sign=S.getSignIn(state.system,now()),claimedCount=sign.todayClaimed?((sign.streak-1)%7)+1:sign.streak%7;
   return `<article class="checkin-card"><div class="card-head"><div><span class="section-kicker">每天来看看</span><h2>七日田园签到</h2></div><span class="tag">连签 ${sign.streak} 天</span></div><p class="helper">点选日期查看奖励，第 7 天领积分优惠券。</p><div class="checkin-grid" role="list" aria-label="七日签到奖励">${sign.rewards.map((r,i)=>`<div role="listitem" class="checkin-cell">${btn('x-signin-preview',`<span>第 ${r.day} 天</span>${icon(i<claimedCount?'check':r.reward.points?'sprout':r.reward.coupon?'gift':'bag')}<small>${r.reward.points?r.reward.points+' 积分':r.reward.coupon?'积分券':'农场物资'}</small>`,`checkin-day ${i<claimedCount?'claimed':''} ${i===sign.nextIndex&&!sign.todayClaimed?'active':''}`,`data-day="${r.day}" aria-label="第${r.day}日，${r.label}，${i<claimedCount?'已领取':i===sign.nextIndex&&!sign.todayClaimed?'今日可签到':'待签到'}，查看奖励"`)}</div>`).join('')}</div>${btn('x-signin',sign.todayClaimed?'今日已签到，明天再来':`签到领取 ${sign.rewards[sign.nextIndex]?.label||'田园心意'}`,'primary-button full',sign.todayClaimed?'disabled':'')}<p class="helper">按北京时间每日签到；断签后重新积累连续天数。奖励均为 Demo 资源。</p></article>`;
  }
  function taskFilterControls(){
   const tasks=S.getTasks(state.system,now()),counts={all:tasks.length,ready:tasks.filter(t=>t.ready&&!t.claimed).length,todo:tasks.filter(t=>!t.ready&&!t.claimed).length,claimed:tasks.filter(t=>t.claimed).length};
   return `<div class="task-filters" role="group" aria-label="每日任务筛选">${taskFilters.map(([key,label])=>btn('x-task-filter',`${label}<span>${counts[key]}</span>`,'discovery-chip',`data-filter="${key}" aria-pressed="${(state.activityTaskFilter||'all')===key}"`)).join('')}</div>`;
  }
  function seasonCard(){const s=S.getSeasonStatus(state.system,now()),tasks=S.getTasks(state.system,now());return `<article class="season-card"><div><span class="section-kicker">当季特别活动</span><h2>丰收季 · 集齐田园三章</h2><p>领取今日三项任务奖励，再收一份丰收礼。</p></div><div class="stamp-grid">${tasks.map(t=>`<div class="stamp ${t.claimed?'completed':''}">${icon(t.claimed?'checkCircle':t.id==='browse'?'leaf':t.id==='care'?'drop':'basket')}<span>${t.id==='browse'?'逛田园':t.id==='care'?'做照料':'有收获'}</span></div>`).join('')}</div>${btn('x-claim-season',s.claimed?'今日丰收礼已领取':s.ready?'领取 30 积分 + 饲料 + 券':`已集齐 ${s.count} / ${s.total} 枚印章`,'primary-button full claim-button',!s.ready||s.claimed?'disabled':'')}<p class="helper">奖励不改变实际种养的次数、间隔或成熟时间。</p></article>`;}
  function achievements(embedded=false){const heading=embedded?'h2':'h1';const l=S.getLevel(state.system);return `<div class="growth-hero"><span class="section-kicker">每一份照料，都算数</span><span class="photo-source">AI生成示意</span><${heading}>Lv.${l.level} · ${l.label}</${heading}><div class="growth-row"><span>成长值 ${l.xp}</span><span>${l.next?'距下一级 '+(l.next-l.xp):'已达当前最高等级'}</span></div><div class="progress"><span style="width:${l.progress}%"></span></div><p>成长只记录田园历程，不增加农事额度。</p></div>${S.getAchievements(state.system).map((a,i)=>`<article class="achievement-card"><div class="achievement-medal ${a.ready?'earned':''}">${icon(['drop','seed','basket','clock'][i])}</div><div class="task-copy"><h2>${a.title}</h2><p>${a.description}</p><span class="task-reward">+ ${rewardText(a.reward)}</span><div class="achievement-progress-label">累计 ${a.progress} / ${a.target}</div><div class="achievement-progress" role="progressbar" aria-label="${a.title}进度" aria-valuemin="0" aria-valuemax="${a.target}" aria-valuenow="${Math.min(a.progress,a.target)}"><span style="width:${Math.min(100,a.progress/a.target*100)}%"></span></div></div>${btn('x-claim-achievement',a.claimed?'已领取':a.ready?'领取':'未达成',a.ready?'primary-button':'outline-button',`data-achievement="${a.id}" ${a.claimed||!a.ready?'disabled':''}`)}</article>`).join('')}`;}
  function nextActivity(){
   const sign=S.getSignIn(state.system,now()),tasks=S.getTasks(state.system,now()),season=S.getSeasonStatus(state.system,now());
   if(!sign.todayClaimed)return {title:'今天，先收一份签到礼',description:`本日可领 ${sign.rewards[sign.nextIndex].label}，收入你的积分与仓库。`,action:'x-signin',label:'领取今日签到'};
   const task=tasks.find(t=>t.ready&&!t.claimed);
   if(task)return {title:`${task.title}，奖励可以领了`,description:`这项农事已达成，领取 ${rewardText(task.reward)}，再添一枚丰收印章。`,action:'x-claim-task',label:`领取 ${rewardText(task.reward)}`,attrs:`data-task="${task.id}"`};
   if(season.ready&&!season.claimed)return {title:'三枚印章，换一份丰收礼',description:'今日三项任务奖励已领取，丰收积分、饲料与积分券正在等你。',action:'x-claim-season',label:'领取今日丰收礼'};
   const achievement=S.getAchievements(state.system).find(a=>a.ready&&!a.claimed);
   if(achievement)return {title:`达成「${achievement.title}」`,description:`新成就已达成，领取 ${rewardText(achievement.reward)}，留住这份成长。`,action:'x-claim-achievement',label:'领取成就奖励',attrs:`data-achievement="${achievement.id}"`};
   const browse=tasks.find(t=>t.id==='browse'&&!t.claimed&&!t.ready);
   if(browse)return {title:'逛逛商城，备一点田园所需',description:'看当季认养，或挑选日常物资，回来领取今日逛商城积分。',action:'x-task-go',label:'去逛农场商城',attrs:'data-task="browse"'};
   const harvest=tasks.find(t=>t.id==='harvest'&&!t.claimed&&!t.ready);
   if(harvest&&state.eggs)return {title:`鸡舍里有 ${state.eggs} 枚鸡蛋待收取`,description:'把今天的小新鲜收入收获篮，再来领取每日任务奖励。',action:'x-task-go',label:'去收取鸡蛋',attrs:'data-task="harvest"'};
   const care=tasks.find(t=>t.id==='care'&&!t.claimed&&!t.ready),canCare=state.animals.some(p=>p.status==='growing'&&ctx.eligibility(p,'feed').allowed)||state.plots.some(p=>p.status==='growing'&&ctx.eligibility(p,'water').allowed);
   if(care&&canCare)return {title:'按需照料，刚刚好就好',description:'看看当前需要浇水或投喂的对象，照料成功后再领积分。',action:'x-task-go',label:'去照料一次',attrs:'data-task="care"'};
   const mature=[...state.plots,...state.animals].find(p=>p.status==='ready'&&!ctx.shipmentFor(p.id));
   if(harvest&&mature)return {title:`${mature.name}，等你看看`,description:'到农场查看可收获对象，按流程预约并完成模拟采收或处理。',action:'x-ready-object',label:'查看成熟对象',attrs:`data-id="${mature.id}"`};
   return {title:season.claimed?'今天的丰收礼，已收入囊中':'让田园慢慢生长',description:season.claimed?'可以去仓库看看收获，明天再来收一份新的心意。':'当前没有可直接领取的奖励。照料次数与间隔仍以农场状态为准。',action:season.claimed?'warehouse':'farm',label:season.claimed?'看看我的仓库':'回农场看看'};
  }
  function latestReward(){const r=state.rewardHistory.at(-1);return r?btn('rewards',`${icon('checkCircle')}<span><strong>最近到账 · ${esc(r.title)}</strong><small>+ ${esc(rewardText(r.reward))}</small></span>${icon('chevron')}`,'reward-latest'):'';}
  function activityOverview(){
   const sign=S.getSignIn(state.system,now()),tasks=S.getTasks(state.system,now()),season=S.getSeasonStatus(state.system,now()),ready=tasks.filter(t=>t.ready&&!t.claimed).length;
   const next=nextActivity();
   return `<section class="activity-overview" aria-labelledby="activity-overview-title"><div class="activity-overview-head"><h2 id="activity-overview-title">今天的田园心意</h2><span>${ready?ready+' 项可领':'完成农事，再领积分'}</span></div><div class="activity-next"><span class="activity-next-kicker">${icon('leaf')}接下来，做这件小事</span><h3>${esc(next.title)}</h3><p>${esc(next.description)}</p>${btn(next.action,next.label+icon('chevron'),'primary-button',`data-guide="next" ${next.attrs||''}`)}</div><p class="activity-overview-stamps">丰收季 · ${season.count} / ${season.total} 枚印章${season.claimed?' · 丰收礼已领取':season.ready?' · 丰收礼待领取':''}</p><div class="activity-overview-actions">${btn('x-signin-calendar',sign.todayClaimed?'今日签到已领取':'七日签到奖励','outline-button',sign.todayClaimed?'disabled':'')}${btn('tasks',ready?`每日任务 · ${ready} 项可领`:'每日任务 · 去完成','outline-button')}${btn('welfare','新人和好友福利'+icon('chevron'),'outline-button')}</div><div class="activity-reward-links">${btn('rewards',`${icon('list')}奖励明细`,'link-button')}${btn('warehouse',`${icon('box')}去仓库看看`,'link-button')}</div></section>`;
  }
  function activities(){return `<div class="activity-hero"><span class="section-kicker">HEJIAN · 田园活动</span><span class="photo-source">AI生成示意</span>${btn('x-activity-rules',icon('help')+'活动说明','link-button activity-rules-link')}<h1>日常有心意</h1><p>来田园，攒心意。</p></div>${goalCard()}${activityOverview()}${latestReward()}<div class="activity-tabs" role="group" aria-label="活动内容">${btn('x-activity-tab','今日活动',state.activityTab==='today'?'active':'','data-tab="today" aria-pressed="'+(state.activityTab==='today')+'"')}${btn('x-activity-tab','成长成就',state.activityTab==='growth'?'active':'','data-tab="growth" aria-pressed="'+(state.activityTab==='growth')+'"')}</div>${state.activityTab==='growth'?achievements(true):`${signInCard()}${section('今日农事','tasks','全部任务')}${taskFilterControls()}${taskCards(true)}${seasonCard()}${section('和朋友一起，来田园坐坐')}<div class="card"><div class="card-head"><h3>新人有礼，好友有伴</h3>${icon('gift')}</div><p class="helper">新人礼、完整观看广告和有效邀请，收一份田园心意。</p><div class="modal-actions">${btn('ad','看广告领奖','outline-button',state.wallet.adToday>=3?'disabled':'')}${btn('invite','邀请朋友','primary-button')}</div>${btn('welcome',state.wallet.welcomeClaimed?'新人礼已领取':'领取新人见面礼','link-button full',state.wallet.welcomeClaimed?'disabled':'')}</div>`}`;}
  function rewardParts(r){
   const items=[['points','积分','积分余额','sprout'],['feed','份饲料','我的仓库','bag'],['fertilizer','份肥料','我的仓库','leaf'],['tools','件工具','我的仓库','shield'],['seedPacks','份种子盒','我的仓库','seed'],['decorations','件装扮','我的仓库','gift']];
   return `<ul class="reward-parts">${items.filter(([key])=>r[key]).map(([key,label,destination,ic])=>`<li>${icon(ic)}<strong>+ ${r[key]} ${label}</strong><span>已收入${destination}</span></li>`).join('')}${r.coupon?`<li>${icon('gift')}<strong>+ 1 张积分券</strong><span>${esc(r.coupon.title)} · 我的优惠券</span></li>`:''}</ul>`;
  }
  function rewards(){
   const origin=state.rewardOrigin||'activities',labels={activities:'返回活动',tasks:'返回今日农事',achievements:'返回成长成就',mine:'返回我的',warehouse:'返回仓库'},history=state.rewardHistory,day=D.chinaDayKey(now()),totals=R.summarize(history,day);
   const heading=back(origin,labels[origin])+pageHead('活动奖励明细','每一份心意，来处和去向都清楚。');
   if(!history.length)return heading+`<div class="empty">${icon('gift')}<h2>还没有活动奖励记录</h2><p>完成签到或领取任务、集章、成就奖励后，可以在这里回看到账明细。</p>${btn('activities','去活动中心','primary-button')}</div><p class="helper">仅记录本次页面体验中的活动奖励，刷新后清空。</p>`;
   let lastDay='';
   const entries=history.slice().reverse().map(r=>{const entryDay=D.chinaDayKey(r.at),date=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(r.at)),separator=entryDay!==lastDay?`<h2 class="reward-day">${esc(entryDay)}${entryDay===day?' · 今天':''}</h2>`:'';lastDay=entryDay;return separator+`<article class="reward-receipt"><div class="reward-receipt-heading"><div><h3>${esc(r.title)}</h3><time datetime="${new Date(r.at).toISOString()}">${date} · 北京时间</time></div><span class="reward-source">${{signin:'签到',task:'每日任务',season:'丰收集章',achievement:'成长成就'}[r.source]}</span></div>${rewardParts(r.reward)}</article>`;}).join('');
   return heading+`<div class="reward-history-head"><h2>今日到账</h2><span>${day}</span></div><div class="reward-statistics" aria-label="今日活动到账汇总"><div><strong>+${totals.points}</strong><span>田园积分</span></div><div><strong>${totals.materials}</strong><span>份 / 件物资</span></div><div><strong>${totals.coupons}</strong><span>张积分券</span></div></div><p class="helper">记录签到、每日任务、丰收集章与成长成就。以下 ${history.length} 笔仅在本次页面体验中保留，刷新后清空。</p>${entries}<div class="reward-destinations">${btn('warehouse','查看我的仓库','outline-button')}${btn('coupons','查看积分优惠券','outline-button')}</div>`;
  }
  function cart(){const q=S.quoteCart(state.system,{couponId:state.selectedCoupon});if(!q.count)return `${back('shop','返回商城')}${pageHead('积分购物车','为农场补齐刚刚好的日常所需。')}<div class="cart-empty empty">${icon('bag')}<h2>还没有装进田园心意</h2><p>去挑选饲料、肥料和一份丰收好礼。</p>${btn('x-store-supplies','逛逛农场物资','primary-button')}</div>`;
   return `${back('shop','返回商城')}${pageHead('积分购物车',`已选 ${q.count} 件 · 使用田园积分兑换`)}<div class="card" style="padding:0 15px">${q.items.map(p=>`<div class="cart-row"><div class="crop-picture">${art(p.art)}</div><div class="cart-item-copy"><h2>${p.title}</h2><p>${p.cost} 积分 / 件</p>${quantity(p,p.quantity)}</div><strong>${p.lineTotal}</strong></div>`).join('')}</div><div class="card"><div class="card-head"><h2>积分优惠券</h2>${btn('coupons','查看全部','link-button')}</div><div class="choice-list" style="margin-top:13px">${btn('x-coupon','不使用优惠券',`coupon-choice ${!state.selectedCoupon?'selected':''}`,'data-coupon="" aria-pressed="'+(!state.selectedCoupon)+'"')}${state.system.coupons.filter(c=>!c.used).map(c=>btn('x-coupon',`<span>${c.title}</span><small>${q.subtotal>=c.min?'可抵 '+c.off+' 积分':'还差 '+(c.min-q.subtotal)+' 积分'}</small>`,`coupon-choice ${state.selectedCoupon===c.id?'selected':''}`,`data-coupon="${c.id}" aria-pressed="${state.selectedCoupon===c.id}" ${q.subtotal<c.min?'disabled':''}`)).join('')}</div></div><div class="checkout-summary card"><div class="summary-row"><span>商品积分</span><strong>${q.subtotal}</strong></div><div class="summary-row"><span>优惠抵扣</span><strong>− ${q.discount}</strong></div><div class="summary-row total"><span>实付积分</span><strong>${q.total} 积分</strong></div><p class="helper">当前可用 ${state.wallet.points} 积分${state.wallet.points<q.total?'，积分不足，可在活动中完成任务领取。':''}</p></div><div class="checkout-footer">${btn('x-checkout',state.wallet.points<q.total?'积分不足，先做任务':`确认结算 · ${q.total} 积分`,'primary-button full',state.wallet.points<q.total?'disabled':'')}${state.wallet.points<q.total?btn('activities','去活动中心领积分','link-button full'):''}</div>`;
  }
  function warehouse(){const inventory=state.system.inventory,items=[['feed','日常饲料',state.wallet.feed,'份','feed','x-use-feed'],['fertilizer','田园养护肥',inventory.fertilizer,'份','fertilizer','x-use-fertilizer'],['tools','农事工具',inventory.tools,'件','tools','x-use-tools'],['seedPacks','当季种子盒',inventory.seedPacks,'份','seed','x-use-seeds'],['decorations','庄园装扮',inventory.decorations,'件','sign','x-decor']];return `${back()}${pageHead('我的仓库','农场物资在这里，按需取用。')}<div class="store-wallet"><div><span>田园积分</span><strong>${state.wallet.points}</strong></div>${btn('x-store-supplies','补充物资','outline-button')}</div><div class="warehouse-grid">${items.map(([key,name,qty,unit,svg,a])=>`<article class="warehouse-item"><div class="goods-art" aria-hidden="true">${art(svg)}</div><h2>${name}</h2><strong class="warehouse-count">${qty}<small> ${unit}</small></strong>${btn(a,qty?(key==='seedPacks'?'去选种':key==='decorations'?'布置农场':'去使用'):'去补充','outline-button full inventory-use',`aria-label="${qty?'使用':'补充'}${name}" data-empty="${qty?'0':'1'}"`)}</article>`).join('')}</div>${section('我的收获篮')}<div class="card"><div class="metrics"><div class="metric"><small>鸡蛋累计收取</small><strong>${inventory.eggs}<span>枚</span></strong></div><div class="metric"><small>蔬菜累计采收</small><strong>${inventory.crops}<span>批</span></strong></div><div class="metric"><small>肉类累计处理</small><strong>${inventory.meat}<span>批</span></strong></div></div><p class="helper">累计收获用于回顾田园历程；寄送安排以收获订单为准。</p>${btn('deliveries','查看收获与配送','outline-button full')}</div>${section('最近兑换','exchanges','全部记录')}<div class="ledger-list">${state.system.purchases.length?state.system.purchases.slice(-4).reverse().map(p=>`<div class="purchase-mini"><div>${icon('bag')}<span>${p.items.map(i=>i.title+' ×'+i.quantity).join('、')}</span></div><strong>−${p.total} 积分</strong></div>`).join(''):'<p class="helper">兑换的物资会自动收入这里，还没有兑换记录。</p>'}</div>`;}
  function coupons(){const available=state.system.coupons.filter(c=>!c.used).length,to=state.couponOrigin||'mine';return `${back(to,returnLabel(to))}${pageHead('我的优惠券',`${available} 张可用 · 仅抵扣积分商城`)}${state.system.coupons.map(c=>`<article class="card coupon-card ${c.used?'used':''}"><div class="card-head"><div><span class="section-kicker">田园积分专享</span><h2>${c.title}</h2></div><span class="tag ${c.used?'':'gold'}">${c.used?'已使用':'可使用'}</span></div><p class="helper">物资与积分好礼满 ${c.min} 积分，抵 ${c.off} 积分；每张限用一次。认养演示金额不参与此抵扣。</p>${btn('x-store-supplies',c.used?'再看看商城':'去使用','outline-button full',c.used?'disabled':'')}</article>`).join('')}<p class="helper">签到第 7 天或集齐当日丰收印章，可获得新的积分券。</p>`;}
  function exchanges(){
   const to=state.exchangeOrigin||'shop',purchases=state.system.purchases;
   const start=`${back(to,returnLabel(to))}${pageHead('积分兑换记录',`${purchases.length} 笔兑换 · 仅记录本次页面体验`)}<p class="helper">积分物资已收入农场仓库；本页没有现金交易或实物发货订单。</p>`;
   if(!purchases.length)return `${start}<div class="empty">${icon('bag')}<h2>还没有积分兑换记录</h2><p>兑换农场物资后，可以在这里核对数量和积分。</p>${btn('x-store-supplies','逛逛农场物资','primary-button')}</div>`;
   return start+purchases.slice().reverse().map((p,index)=>`<article class="exchange-card"><div class="card-head"><h2>第 ${purchases.length-index} 笔积分兑换</h2><time class="exchange-date" datetime="${esc(p.day)}">${esc(p.day)}</time></div><ul class="exchange-items">${p.items.map(item=>`<li><span>${esc(item.title)} × ${item.quantity}</span><strong>${item.lineTotal} 积分</strong></li>`).join('')}</ul><div class="exchange-summary"><div class="summary-row"><span>商品积分</span><strong>${p.subtotal} 积分</strong></div><div class="summary-row"><span>优惠抵扣</span><strong>− ${p.discount} 积分</strong></div><div class="summary-row total"><span>实付积分</span><strong>${p.total} 积分</strong></div></div><p class="helper">共 ${p.count} 件 · ${p.couponId?'已使用积分优惠券':'未使用积分优惠券'} · 物资已收入仓库</p>${btn('warehouse','查看仓库','outline-button full')}</article>`).join('');
  }
  function album(){const discovered=new Set([...state.plots.filter(p=>p.status!=='empty').map(p=>p.art),...state.animals.map(p=>p.art),...state.orders.map(o=>ctx.products.find(p=>p.id===o.product)?.art)]);return `${back('mine','返回我的')}${pageHead('我的种养图鉴','一份认养，解锁一段田园故事。')}<div class="collection-summary"><strong>${ctx.products.filter(p=>discovered.has(p.art)).length}</strong><span> / ${ctx.products.length} 种已相遇</span><p>完成模拟认养，记录新的种养品种。</p></div><div class="album-grid">${ctx.products.map(p=>{const owned=discovered.has(p.art);return btn('x-album-detail',`<div class="album-art">${p.type==='animal'?animalArt(p.art):cropArt(p.art)}</div><strong class="album-name">${p.name}</strong><span>${owned?'已相遇':'待认养'}</span>`,`album-card ${owned?'':'locked'}`,`data-product="${p.id}" aria-label="查看${p.name}图鉴"`);}).join('')}</div>`;}
  function messages(){return `${back('mine','返回我的')}${pageHead('农场消息','照料、收获与田园新鲜事。')}<article class="message-card"><span class="message-dot"></span><div><h2>田园商城与丰收季活动已开放</h2><p>签到做农事，领取积分；兑换物资后可在仓库查看。</p><span class="message-time">系统消息 · H5 体验</span></div></article>${state.logs.slice(0,15).map((l,i)=>`<article class="message-card"><span class="message-dot ${i?'read':''}"></span><div><h2>${esc(l.text)}</h2><p>${esc(l.note)}</p><span class="message-time">农场记录 · 模拟状态</span></div></article>`).join('')}`;}
  function mine(html){const level=S.getLevel(state.system);let result=html.replace('<div class="account-stats">',`<div class="profile-growth">${btn('achievements',`<span class="level-chip">Lv.${level.level}</span><span><strong>${level.label}</strong><small>成长值 ${level.xp}${level.next?' / '+level.next:''}</small></span>${icon('chevron')}`,'full')}<div class="progress"><span style="width:${level.progress}%"></span></div></div><div class="account-stats">`);const idx=result.indexOf('<div class="menu-list">');if(idx>=0)result=result.slice(0,idx)+`<div class="farm-shortcuts">${[['warehouse','box','我的仓库'],['coupons','gift','优惠券'],['album','leaf','种养图鉴'],['messages','bell','农场消息']].map(([a,ic,t])=>btn(a,`${icon(ic)}<span>${t}</span>`,'shortcut')).join('')}</div>`+result.slice(idx);return (result+`<div class="menu-list">${btn('rewards',`${icon('list')}<span>活动奖励明细</span>${icon('chevron')}`,'menu-row')}${btn('guide',`${icon('help')}<span>使用帮助与体验说明</span>${icon('chevron')}`,'menu-row')}</div>`).replace('data-action="welfare"','data-action="activities"').replace('福利中心','活动中心').replace('新人 · 广告 · 邀请','签到 · 农事 · 邀友');}
  function renderPage(view){
   if(view==='activities')return activities();if(view==='cart')return cart();if(view==='warehouse')return warehouse();if(view==='coupons')return coupons();if(view==='exchanges')return exchanges();if(view==='rewards')return rewards();if(view==='album')return album();if(view==='messages')return messages();
   if(view==='achievements')return back('activities','返回活动')+achievements()+btn('rewards',icon('list')+'查看活动奖励明细','outline-button full');
   if(view==='tasks')return back()+pageHead('今日农事','做三件小事，收一份田园心意。')+todayPanel()+taskCards()+seasonCard()+btn('rewards',icon('list')+'查看活动奖励明细','outline-button full');
   return null;
  }
  function goodsGrants(p){
   const resources={feed:['日常饲料','份','同一饲料余额 · 我的仓库'],fertilizer:['田园养护肥','份','我的仓库'],tools:['农事工具','件','我的仓库'],seedPacks:['当季种子盒','份','我的仓库'],decorations:['庄园装扮','件','我的仓库']};
   return `<section class="goods-grants" aria-label="每件包含的物资与去向"><h4>每件包含</h4><ul>${Object.entries(p.grant).map(([key,amount])=>{const [title,unit,destination]=resources[key];return `<li><div><span>${title}</span><strong>${amount} ${unit}</strong></div><p>兑换后收入${destination}</p></li>`;}).join('')}</ul></section>`;
  }
  function goodsModal(m){
   const p=catalog.find(p=>p.id===m.sku);if(!p)return null;
   const a=goodsAvailability(p),g=F.goal(catalog,state.wallet,p.id),wished=wishIds().includes(p.id);
   return ctx.frame('田园物资详情',`<div class="goods-art" aria-hidden="true">${art(p.art)}</div><h3 style="font-size:23px;margin-top:15px">${p.title}</h3><p class="sheet-intro" style="margin-top:10px">${p.description}</p><div class="goods-detail-summary"><div class="summary-row"><span>兑换价格</span><strong>${p.cost} 积分 / 件</strong></div><div class="summary-row"><span>可用田园积分</span><strong>${state.wallet.points} 积分</strong></div><div class="summary-row"><span>今日剩余</span><strong>${a.remaining} 件</strong></div><div class="summary-row"><span>车中</span><strong>${a.inCart} 件</strong></div><div class="summary-row"><span>还可加</span><strong>${a.canAdd} 件</strong></div></div><div class="goods-wish-actions">${btn('x-wishlist',icon('heart')+(wished?'取消心愿':'存入心愿'),'outline-button full',`data-sku="${p.id}" aria-pressed="${wished}"`)}${g.shortfall?`<p>还差 ${g.shortfall} 积分可兑一件</p>${btn('x-earn-goal','去活动攒积分','outline-button full',`data-sku="${p.id}"`)}`:''}<small>按单件原价展示；心愿刷新清空，券在结算核对。</small></div>${goodsGrants(p)}<div class="info">${icon('shield')}<span>每次加入 1 件，加入购物车不锁定库存。结算时核对积分和优惠券；物资不增加浇水或投喂次数，全部为演示资源。</span></div>${btn('x-add-cart',a.unavailable||'加入购物车','primary-button full',`data-sku="${p.id}" ${a.canAdd===0?'disabled':''}`)}${btn('x-modal-cart','查看购物车','link-button full')}`);
  }
  function renderModal(m){
   if(m.type==='signin-preview'){
    const sign=S.getSignIn(state.system,now()),index=Number(m.day)-1,r=sign.rewards[index];if(!r)return null;
    const count=sign.todayClaimed?((sign.streak-1)%7)+1:sign.streak%7,available=index===sign.nextIndex&&!sign.todayClaimed;
    return ctx.frame('七日签到 · 奖励预览',`<div class="signin-preview"><div class="signin-preview-icon">${icon(r.reward.coupon?'gift':r.reward.points?'sprout':'bag')}</div><span class="section-kicker">第 ${r.day} 天</span><h3>${esc(r.label)}</h3><p>${esc(rewardText(r.reward))}</p><span class="tag">${index<count?'本轮已领取':available?'今日可领取':'连续签到后领取'}</span></div><div class="info">${icon('clock')}<span>查看预览不会发放奖励。按北京时间签到，同一天只能领取一次；断签后重新积累。</span></div>${available?btn('x-signin','领取今日签到','primary-button full'):btn('close','知道了，回到活动','outline-button full')}`);
   }
   if(m.type==='activity-rules')return ctx.frame('活动说明',`<p class="sheet-intro">所有奖励均为 Demo 资源；领取结果会显示在活动奖励明细。</p><ol class="activity-rules"><li><h3>每天来看看</h3><p>签到与每日任务按北京时间 00:00 更新。断签后重新积累连续天数，同一天不能重复领取。</p></li><li><h3>先完成，再领取</h3><p>逛商城、成功照料、完成演示收获后，各领取一次任务奖励。领取三项奖励后，才能收取当天丰收集章礼。</p></li><li><h3>照料刚刚好</h3><p>积分、饲料与优惠券不会解除农事次数与间隔，也不会提前让作物或牲畜成熟。</p></li><li><h3>到账随时可看</h3><p>积分收入同一余额，物资进入我的仓库，积分券进入我的优惠券。活动明细只保留本次页面体验，刷新后清空。</p></li></ol>${btn('close','知道了，回活动','primary-button full')}`);
   if(m.type==='goods-detail')return goodsModal(m);
   if(m.type==='checkout'){const q=S.quoteCart(state.system,{couponId:state.selectedCoupon});return ctx.frame('确认积分兑换',`<p class="sheet-intro">${q.count} 件物资会收入“我的仓库”，本次只消耗田园积分。</p><div class="checkout-summary">${q.items.map(p=>`<div class="summary-row"><span>${p.title} × ${p.quantity}</span><strong>${p.lineTotal} 积分</strong></div>`).join('')}<div class="summary-row"><span>优惠抵扣</span><strong>− ${q.discount} 积分</strong></div><div class="summary-row total"><span>本次实付</span><strong>${q.total} 积分</strong></div></div><div class="info">${icon('box')}<span>兑换成功后发放物资并核销优惠券。余额或库存不足时不扣积分、不发物资。</span></div><div class="modal-actions">${btn('close','再看看','outline-button')}${btn('x-confirm-checkout','确认兑换','primary-button',state.commerceBusy?'disabled':'')}</div>`);}
   if(m.type==='exchange-success')return ctx.frame('物资已收入仓库',`<div class="reward-panel success"><div class="reward-icon">${icon('checkCircle')}</div><h3>田园所需，已经备好。</h3><p>本次兑换 ${m.count} 件，共使用 ${m.total} 积分。<br>物资已加入你的农场仓库。</p></div><div class="modal-actions">${btn('x-modal-warehouse','查看仓库','primary-button')}${btn('x-modal-store','继续逛商城','outline-button')}</div>`);
   if(m.type==='task-harvest')return ctx.frame('收一份今日的小新鲜',`<div class="harvest-art" style="text-align:center">${cropArt('egg')}</div><h3 style="font-size:23px;text-align:center">${state.eggs?`鸡舍里有 ${state.eggs} 枚鸡蛋`:'今天的鸡蛋，已收入收获篮'}</h3><p class="sheet-intro" style="text-align:center;margin-top:13px">收取后会计入今日收获任务与累计收获记录。</p>${btn('x-collect-eggs',state.eggs?'收取鸡蛋 · 演示':'已收取，查看今日任务','primary-button full')}<p class="helper">本次为模拟收获，实际产量以农场记录为准。</p>`);
   if(m.type==='decor'){const owned=new Set(state.system.purchases.flatMap(p=>p.items.map(i=>i.id)));return ctx.frame('布置自己的一方田',`<p class="sheet-intro">让每次打开农场，都有一点自己的心意。已兑换的装扮可以重复切换。</p><div class="choice-list">${['garden-sign','harvest-frame'].filter(id=>owned.has(id)).map(id=>{const p=catalog.find(p=>p.id===id);return btn('x-apply-decor',`<span>${p.title}</span><span>${state.decoration===id?'已布置':'布置'}</span>`,`choice ${state.decoration===id?'selected':''}`,`data-decoration="${id}"`);}).join('')}${btn('x-apply-decor','恢复自然田园','choice','data-decoration=""')}</div>${!owned.size?`<div class="info">${icon('gift')}<span>还没有庄园装扮，去积分好礼挑一份喜欢的田园木牌或纪念相框。</span></div>${btn('x-modal-gifts','逛逛积分好礼','primary-button full')}`:''}`);}
   if(m.type==='album-detail'){const p=ctx.products.find(p=>p.id===m.product);return ctx.frame(p.name,`<div class="goods-art" aria-hidden="true">${p.type==='animal'?animalArt(p.art):cropArt(p.art)}</div><p class="sheet-intro" style="margin-top:17px">${p.note}</p><div class="summary-row"><span>参考种养周期</span><strong>约 ${p.days} 天</strong></div><div class="info">${icon('leaf')}<span>图鉴记录与品种资料为演示。实际季节、饲养与采收安排需结合农场条件。</span></div>${btn('x-modal-adopt','去看看当季认养','primary-button full')}`);}
   return null;
  }
  function onAdoption(o,p){if(p.type==='crop'&&state.system.inventory.seedPacks>0){state.system.inventory.seedPacks--;o.seedBoxUsed=true;ctx.addLog(`${o.target} 本次播种使用 1 份仓库种子盒`);}track('adoption','adoption-'+o.id);}
  function onHarvest(kind,count,id){track('harvest','harvest-'+id,{[kind]:count});}
  function decorateCare(m,html){const key=m.kind==='fertilize'?'fertilizer':'tools',qty=state.system.inventory[key],label=m.kind==='fertilize'?'养护肥':'农事工具';let out=html.replace('<div class="info">',`<div class="summary-row"><span>仓库可用${label}</span><strong>${qty} ${key==='tools'?'件':'份'}</strong></div><div class="info">`);if(!qty)out=out.replace(/<button[^>]*data-action="request-care"[^>]*>/,tag=>tag.includes(' disabled')?tag:tag.slice(0,-1)+' disabled>');return out.replace('请求工作人员查看 · 演示',`使用 1 ${key==='tools'?'件工具':'份肥料'}并提交安排`);}
  function consumeCare(m){const key=m.kind==='fertilize'?'fertilizer':'tools';if(state.system.inventory[key]<1){ctx.toast('仓库物资不足，可先到农场商城补充');return false;}state.system.inventory[key]--;return true;}
  function decorateBuy(m,html){const p=ctx.products.find(p=>p.id===m.id);return p?.type==='crop'&&state.system.inventory.seedPacks?html.replace('<span class="field-label">',`<div class="info">${icon('seed')}<span>仓库有 ${state.system.inventory.seedPacks} 份种子盒，本次演示播种会自动使用 1 份。示例金额不会实际扣款。</span></div><span class="field-label">`):html;}
  function handleAction(a,target){
   if(!a.startsWith('x-'))return false;
   const sku=target.dataset.sku;
   if(a==='x-search-clear'){state.shopQuery='';state.shopDraft='';ctx.render();focusSearch();return true;}
   if(a==='x-discovery-reset'){state.shopQuery='';state.shopDraft='';state.shopFilter='all';ctx.render();focusSearch();return true;}
   if(a==='x-shop-filter'){if(shopFilters.some(([key])=>key===target.dataset.filter)){state.shopFilter=target.dataset.filter;ctx.render();}return true;}
   if(a==='x-wishlist'){state.shopWishlist=F.toggleWishlist(catalog,wishIds(),sku);if(!wishIds().includes(state.savingGoalSku))state.savingGoalSku='';ctx.render();ctx.renderModal();ctx.toast(wishIds().includes(sku)?'已存入心愿，本次体验可回看':'已取消这份心愿');return true;}
   if(a==='x-earn-goal'){const p=catalog.find(p=>p.id===sku);if(!p)return true;if(!wishIds().includes(sku))state.shopWishlist=F.toggleWishlist(catalog,wishIds(),sku);state.savingGoalSku=sku;ctx.close();ctx.navigate('activities');return true;}
   if(a==='x-goal-clear'){state.savingGoalSku='';ctx.render();ctx.toast('已结束攒分目标，心愿商品仍保留');return true;}
   if(a==='x-goal-detail'){const p=catalog.find(p=>p.id===state.savingGoalSku);if(p){state.storefront=p.category;ctx.navigate('shop');ctx.open('goods-detail',{sku:p.id});}return true;}
   if(a==='x-task-filter'){if(taskFilters.some(([key])=>key===target.dataset.filter)){state.activityTaskFilter=target.dataset.filter;ctx.render();}return true;}
   if(a==='x-signin-preview'){const day=Number(target.dataset.day);if(Number.isInteger(day)&&day>=1&&day<=7)ctx.open('signin-preview',{day});return true;}
   if(a==='x-store-tab'){state.storefront=target.dataset.tab;state.selectedCoupon='';if(state.storefront!=='adopt')track('browse','browse-'+D.chinaDayKey(now()));ctx.render();return true;}
   if(a==='x-goods-sort'){if(goodsSortOptions.some(([key])=>key===target.dataset.sort)){state.goodsSort=target.dataset.sort;ctx.render();}return true;}
   if(a==='x-store-supplies'){state.storefront='supplies';ctx.navigate('shop');return true;}
   if(a==='x-activity-tab'){state.activityTab=target.dataset.tab;ctx.render();return true;}
   if(a==='x-activity-rules'){ctx.open('activity-rules');return true;}
   if(a==='x-ready-object'){const p=[...state.plots,...state.animals].find(p=>p.id===target.dataset.id);if(!p||p.status!=='ready'||ctx.shipmentFor(p.id)){ctx.toast('对象状态已有变化，请到农场查看');return true;}const crop=state.plots.includes(p);state.tab=crop?'crop':'animal';if(crop)state.selected=p.id;else state.animal=p.id;ctx.navigate('farm');ctx.focusCare();return true;}
   if(a==='x-signin-calendar'){state.activityTab='today';ctx.render();const h=document.querySelector('.checkin-card h2');if(h){h.tabIndex=-1;h.scrollIntoView({block:'start'});h.focus({preventScroll:true});}return true;}
   if(a==='x-add-cart'||a==='x-quantity'){const p=catalog.find(p=>p.id===sku);if(!p)return true;const r=S.addCart(state.system,sku,a==='x-add-cart'?1:Number(target.dataset.delta),now());if(!r.ok){ctx.toast(r.reason);return true;}state.system=r.system;const q=S.quoteCart(state.system,{couponId:state.selectedCoupon});if(state.selectedCoupon&&!q.couponEligible)state.selectedCoupon='';ctx.render();if(ctx.getModal()?.type==='goods-detail')ctx.renderModal();ctx.toast(a==='x-add-cart'?'已加入购物车，可统一结算':'购物车数量已更新');return true;}
   if(a==='x-goods-detail'){if(catalog.some(p=>p.id===sku))ctx.open('goods-detail',{sku});return true;}
   if(a==='x-coupon'){state.selectedCoupon=target.dataset.coupon||'';ctx.render();return true;}
   if(a==='x-checkout'){const q=S.quoteCart(state.system,{couponId:state.selectedCoupon});if(q.count&&state.wallet.points>=q.total)ctx.open('checkout');return true;}
   if(a==='x-confirm-checkout'){if(ctx.getModal()?.type!=='checkout'||state.commerceBusy)return true;state.commerceBusy=true;const r=S.checkout(state.system,state.wallet,{now:now(),couponId:state.selectedCoupon,receiptId:receipt('checkout')});state.commerceBusy=false;if(!r.ok){ctx.toast(r.reason);return true;}state.system=r.system;state.wallet=r.wallet;state.selectedCoupon='';ctx.addLog(`积分兑换 ${r.purchase.count} 件农场物资`,`消耗 ${r.purchase.total} 积分 · 演示库存已更新`);ctx.render();ctx.open('exchange-success',{count:r.purchase.count,total:r.purchase.total});return true;}
   if(a==='x-signin'){if(claimReward('signIn',{},'signin','七日田园签到')){ctx.addLog('完成今日田园签到','签到奖励已收入积分与仓库 · 演示');if(ctx.getModal()?.type==='signin-preview')ctx.close();}return true;}
   if(a==='x-claim-task'){const task=S.getTasks(state.system,now()).find(t=>t.id===target.dataset.task);claimReward('claimTask',{taskId:target.dataset.task},'task',task?.title||'每日任务');return true;}
   if(a==='x-claim-season'){claimReward('claimSeason',{},'season','丰收季 · 田园三章');return true;}
   if(a==='x-claim-achievement'){const achievement=S.getAchievements(state.system).find(a=>a.id===target.dataset.achievement);claimReward('claimAchievement',{achievementId:target.dataset.achievement},'achievement',achievement?.title||'成长成就');return true;}
   if(a==='x-task-go'){const id=target.dataset.task;if(id==='browse'){state.storefront='supplies';ctx.navigate('shop');}else if(id==='harvest'&&state.eggs)ctx.open('task-harvest');else if(id==='care'){const a=state.animals.find(p=>p.status==='growing'&&ctx.eligibility(p,'feed').allowed);if(a){ctx.open('feed',{id:a.id});}else{const p=state.plots.find(p=>p.status==='growing'&&ctx.eligibility(p,'water').allowed);if(p)ctx.open('water',{id:p.id,duration:3});else ctx.toast('当前认养对象暂不需要照料，间隔结束后再来看看');}}else{state.tab='crop';ctx.navigate('farm');ctx.toast('可在成熟地块预约采收，并模拟完成农场处理');}return true;}
   if(a==='x-collect-eggs'){if(state.eggs)ctx.collectEggs();ctx.close();ctx.navigate('tasks');return true;}
   if(a==='x-modal-cart'||a==='x-modal-warehouse'||a==='x-modal-store'||a==='x-modal-gifts'||a==='x-modal-adopt'){ctx.close();if(a==='x-modal-gifts')state.storefront='gifts';if(a==='x-modal-adopt')state.storefront='adopt';ctx.navigate(a==='x-modal-cart'?'cart':a==='x-modal-warehouse'?'warehouse':'shop');return true;}
   if(a==='x-album-detail'){ctx.open('album-detail',{product:target.dataset.product});return true;}
   if(a==='x-decor'){ctx.open('decor');return true;}
   if(a==='x-apply-decor'){const id=target.dataset.decoration,owned=state.system.purchases.some(p=>p.items.some(i=>i.id===id));if(id&&!owned)return true;state.decoration=id;ctx.close();ctx.navigate('farm');ctx.toast(id?'已为你的一方田换上新装扮':'已恢复自然田园');return true;}
   if(a.startsWith('x-use-')){if(target.dataset.empty==='1'){state.storefront='supplies';ctx.navigate('shop');return true;}if(a==='x-use-feed'){state.tab='animal';const p=state.animals.find(p=>p.status==='growing');if(p){state.animal=p.id;ctx.open('feed',{id:p.id});}else ctx.toast('当前没有需要投喂的牲畜');}else if(a==='x-use-seeds'){state.storefront='adopt';state.shopKind='crop';ctx.navigate('shop');}else{const p=a==='x-use-fertilizer'?state.plots.find(p=>p.status==='growing'):[...state.plots,...state.animals].find(p=>p.status==='growing');if(p)ctx.open('care',{id:p.id,kind:a==='x-use-fertilizer'?'fertilize':'inspect'});else ctx.toast('当前没有需要照料的认养对象');}return true;}
   return false;
  }
  const rewardNavOwner=()=>['mine','warehouse'].includes(state.rewardOrigin)?'mine':'activities';
  const navOwner=view=>view==='rewards'?rewardNavOwner():view==='coupons'?state.couponOrigin==='rewards'?rewardNavOwner():(state.couponOrigin||'mine')==='mine'?'mine':'shop':['activities','tasks','achievements','welfare'].includes(view)?'activities':['shop','cart','exchanges'].includes(view)?'shop':['mine','warehouse','album','messages','orders','deliveries'].includes(view)?'mine':view;
  return {home,shop,mine,renderPage,renderDock,renderModal,handleAction,handleSubmit,handleInput,handleComposition,handleKeyDown,deferRender,track,onAdoption,onHarvest,decorateCare,consumeCare,decorateBuy,beforeNavigate,navigationContext,restoreNavigationContext,navOwner,titles};
 }};
})();
